void create_spark_particle(s32 id, u128 *pos, s32 life, u8 kind, u8 texture_table_index, u8 mode, f32 x, f32 y, f32 z,
                      f32 w, f32 alpha, f32 r, f32 g, f32 b, f32 size) {
    Spark *spark;
    SparkBody *spark_body;
    u128 position_snapshot = *pos;
    u128 *position_copy_source = &position_snapshot;

    if (id == 0) {
        return;
    }
    spark = create_part(6);
    if (spark == 0) {
        return;
    }
    spark_body = &spark->body;
    qcopy(&spark->pos, position_copy_source);
    if (mode == 0xFF) {
        spark->b9 = (kind >> 5) * 16 + truncate_float_to_s32(4.0f);
        if (kind & 1) {
            spark->b3 = 0x48;
        } else {
            spark->b3 = 0x44;
        }
    } else {
        spark->b9 = kind;
        spark->b3 = mode;
    }
    spark->b1 = 0;
    spark->b2 = *D_L01_001B2500[texture_table_index];
    spark_body->x = x;
    spark_body->y = y;
    spark_body->z = z;
    spark_body->f14 = alpha;
    spark_body->r = truncate_float_to_s32(r * 65535.0f);
    spark_body->g = truncate_float_to_s32(g * 65535.0f);
    spark_body->b = truncate_float_to_s32(b * 65535.0f);
    spark_body->f10 = size;
    spark_body->id = id;
    spark->fC = w;
    spark->b8 = alpha * 255.0f;
    spark->hA = scale_game_frames(life);
    spark_body->b1B = 0;
    spark->w4 = FUN_L00_0025bfe0(r, g, b, size);
}
